-- ============================================
-- 全国主要城市对 车次/航班 模拟数据（分表版）
-- 车次 → train_schedule 表，航班 → flight_schedule 表
-- 在 Navicat 中运行本文件即可
-- ============================================

USE travel_plan;

-- ===== 1. 创建车次表 =====
CREATE TABLE IF NOT EXISTS train_schedule (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NULL,
    train_no VARCHAR(20) NOT NULL,
    train_type VARCHAR(5) DEFAULT 'G',
    from_city VARCHAR(50) NOT NULL,
    to_city VARCHAR(50) NOT NULL,
    depart_time VARCHAR(10) NOT NULL,
    arrive_time VARCHAR(10) NOT NULL,
    price DECIMAL(10,2) DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- ===== 2. 创建航班表 =====
CREATE TABLE IF NOT EXISTS flight_schedule (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NULL,
    flight_no VARCHAR(20) NOT NULL,
    airline VARCHAR(10) DEFAULT '',
    from_city VARCHAR(50) NOT NULL,
    to_city VARCHAR(50) NOT NULL,
    depart_time VARCHAR(10) NOT NULL,
    arrive_time VARCHAR(10) NOT NULL,
    price DECIMAL(10,2) DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- ===== 3. 清空旧数据（保留用户自己添加的）并重置自增 =====
DELETE FROM train_schedule WHERE user_id IS NULL;
ALTER TABLE train_schedule AUTO_INCREMENT = 1;
DELETE FROM flight_schedule WHERE user_id IS NULL;
ALTER TABLE flight_schedule AUTO_INCREMENT = 1;

